func deriveSearchVerifySuiteCMake(dir string, evidence *searchVerifyEvidence) *SearchVerifyCommand {
	manifest := searchVerifyJoin(dir, "CMakeLists.txt")
	content, ok := evidence.file(manifest)
	if !ok {
